var n=`0910-char-siu`;var a=`world-0910`;var s=`CN`;var o=`east-asia`;var t=4;var r=420;var h={en:`Char Siu`,ua:`Чар сіу`};var u={en:`Char Siu is a China dish made with pork shoulder, hoisin sauce, light soy sauce, green onion. This home-scale recipe assigns measured ingredients to the steps where they are used. Use a fresh separate glaze; never brush cooked meat with uncooked poultry/meat marinade.`,ua:`Чар сіу, страва кухні країни Китай. Основні складники: свиняча лопатка, соус хойсин, світлий соєвий соус, зелена цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Використовуйте окрему свіжу глазур, не наносіть на готове м’ясо маринад, який контактував із сирим.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 360 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 360 хвилин.`,t:[`marinating`],m:360,i:[[`pork-shoulder`,900,`g`],[`hoisin-sauce`,110,`g`],[`light-soy-sauce`,45,`ml`],[`honey`,60,`g`],[`chinese-five-spice`,8,`g`],[`shaoxing-wine`,40,`ml`]]},{en:`Roast in a preheated 190°C oven for about 45 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 45 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:45,i:[]},{en:`Make a separate clean glaze from fresh soy sauce, water and honey; boil it briefly and brush only onto cooked pork.`,ua:`Приготуйте окрему чисту глазур зі свіжого соєвого соусу, води й меду, коротко прокип’ятіть і наносіть лише на готову свинину.`,t:[`reducing-sauce`],m:8,i:[[`light-soy-sauce`,20,`ml`],[`water`,50,`ml`],[`honey`,35,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:7,i:[[`green-onion`,25,`g`]]}];var d={slug:n,id:a,country:`CN`,region:o,servings:4,minutes:420,title:h,text:u,steps:g};export{s as country,d as default,a as id,r as minutes,o as region,t as servings,n as slug,g as steps,u as text,h as title};